<script setup lang="ts">
import {decorationUnitStyle} from '../../../../api/src/core/decoration-components.mjs'
import type {DecorationBlock,DecorationLink} from '../../../../api/src/core/decoration-types'
import {decorationOptions,noticeItems,decorationLabelStyle} from '../../../../api/src/core/decoration-options.mjs'
const props=defineProps<{block:DecorationBlock;imageUrl:(id:string)=>string;editable?:boolean;primary:string}>()
const emit=defineEmits<{navigate:[target:DecorationLink]}>()
const o=computed(()=>decorationOptions(props.block)),items=computed(()=>noticeItems(props.block)),current=ref(0),popup=ref(false),message=ref(''),root=shallowRef<HTMLElement|null>(null),marqueeHost=shallowRef<HTMLElement|null>(null),marqueeLine=shallowRef<HTMLElement|null>(null),popupHost=shallowRef<HTMLElement|null>(null),overflow=ref(false),duration=ref(3000)
let timer:ReturnType<typeof setInterval>|undefined
function restart(){clearInterval(timer);current.value=0;if(o.value.noticeScroll==='vertical'&&items.value.length>1)timer=setInterval(()=>{current.value=(current.value+1)%items.value.length},3000)}
let observer:ResizeObserver|undefined
function measure(){if(marqueeHost.value&&marqueeLine.value){const width=marqueeLine.value.scrollWidth;overflow.value=marqueeHost.value.clientWidth<width-30;duration.value=Math.ceil(width*14)}}
onMounted(()=>{restart();popupHost.value=root.value?.closest<HTMLElement>('.phone-preview-screen')||document.body;observer=new ResizeObserver(measure);if(marqueeHost.value)observer.observe(marqueeHost.value);nextTick(measure)});watch(()=>[props.block.items,props.block.options],()=>nextTick(measure),{deep:true,flush:'post'});watch(()=>[props.editable,o.value.noticeScroll,items.value.length],restart);onBeforeUnmount(()=>{clearInterval(timer);observer?.disconnect()})
function activate(index:number){if(props.editable)return;const item=items.value[index];if(!item)return;if(o.value.noticeAction==='link')emit('navigate',item.target);else{message.value=item.text||item.label;popup.value=true}}
</script>
<template><div ref="root" class="decoration-notice"><img v-if="o.noticeMode==='image'" class="notice-title-image" :src="o.noticePreset==='custom'&&o.noticeImageId?imageUrl(o.noticeImageId):'/decoration/notice-'+(o.noticePreset==='style2'?2:1)+'.png'" alt="公告"><span v-else class="notice-badge" :style="{color:primary,background:primary+'12'}">{{block.title||'公告'}}</span><div ref="marqueeHost" class="notice-window" :class="{horizontal:o.noticeScroll==='horizontal'}"><div v-if="o.noticeScroll==='vertical'" class="notice-vertical" :style="{transform:'translateY(calc(var(--diy-unit, 1px) * -'+current*24+'))'}"><button v-for="(item,index) in items" :key="item.id" type="button" :style="decorationUnitStyle(decorationLabelStyle(block))" @click="activate(index)">{{item.text||item.label}}</button></div><div v-else class="notice-marquee" :style="{animation:overflow?'':'none',animationDuration:duration+'ms'}"><div ref="marqueeLine" class="marquee-line"><button v-for="(item,index) in items" :key="item.id" type="button" :style="decorationLabelStyle(block)" @click="activate(index)">{{item.text||item.label}}</button></div><div v-if="overflow" class="marquee-line" aria-hidden="true"><button v-for="(item,index) in items" :key="item.id" type="button" tabindex="-1" :style="decorationLabelStyle(block)" @click="activate(index)">{{item.text||item.label}}</button></div></div></div><UIcon v-if="o.noticeScroll==='vertical'" name="i-lucide-chevron-right" class="notice-arrow"/></div><Teleport v-if="popup&&popupHost" :to="popupHost"><div class="notice-overlay" :class="{'in-phone':popupHost.classList.contains('phone-preview-screen')}" @click="popup=false"><div class="notice-popup" @click.stop><h3>公告</h3><div class="notice-popup-text">{{message}}</div><button :style="{background:primary}" @click="popup=false">我知道了</button></div></div></Teleport></template>
<style scoped>.decoration-notice{display:flex;align-items:center;gap:calc(var(--diy-unit, 1px) * 10);min-height:calc(var(--diy-unit, 1px) * 24);padding:calc(var(--diy-unit, 1px) * 11) calc(var(--diy-unit, 1px) * 11) calc(var(--diy-unit, 1px) * 11) calc(var(--diy-unit, 1px) * 14);box-sizing:border-box}.notice-title-image{height:calc(var(--diy-unit, 1px) * 20);max-width:calc(var(--diy-unit, 1px) * 100);object-fit:contain;flex-shrink:0}.notice-badge{max-width:calc(var(--diy-unit, 1px) * 64);padding:0 calc(var(--diy-unit, 1px) * 6);height:calc(var(--diy-unit, 1px) * 20);line-height:calc(var(--diy-unit, 1px) * 20);border-radius:calc(var(--diy-unit, 1px) * 4);font-size:calc(var(--diy-unit, 1px) * 13);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex-shrink:0}.notice-window{flex:1;min-width:0;overflow:hidden;height:calc(var(--diy-unit, 1px) * 24)}.notice-vertical{transition:transform .5s}.notice-vertical button{display:block;width:100%;height:calc(var(--diy-unit, 1px) * 24);line-height:calc(var(--diy-unit, 1px) * 24);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:left;border:0;padding:0;background:none}.notice-marquee{display:flex;align-items:center;width:max-content;height:calc(var(--diy-unit, 1px) * 24);animation:notice-marquee 18s linear infinite;animation-delay:800ms}.notice-marquee button{white-space:nowrap;border:0;padding:0;background:none}.marquee-line{display:flex;gap:calc(var(--diy-unit, 1px) * 40);padding-right:calc(var(--diy-unit, 1px) * 40);flex-shrink:0}.notice-arrow{font-size:calc(var(--diy-unit, 1px) * 13);color:#999;flex-shrink:0}.notice-popup-text{white-space:pre-wrap;font-size:calc(var(--diy-unit, 1px) * 14);line-height:1.8}@keyframes notice-marquee{from{transform:translateX(0)}to{transform:translateX(-50%)}}.notice-overlay{position:fixed;inset:0;z-index:1000;background:#0006;display:flex;align-items:center;justify-content:center}.notice-overlay.in-phone{position:absolute}.notice-popup{width:calc(var(--diy-unit, 1px) * 285);padding:calc(var(--diy-unit, 1px) * 22) calc(var(--diy-unit, 1px) * 16);border-radius:calc(var(--diy-unit, 1px) * 14);background:white;color:#303133}.notice-popup h3{text-align:center;font-size:calc(var(--diy-unit, 1px) * 17);font-weight:600;margin:0 0 calc(var(--diy-unit, 1px) * 20)}.notice-popup-text{max-height:calc(var(--diy-unit, 1px) * 130);overflow:auto;white-space:pre-wrap;font-size:calc(var(--diy-unit, 1px) * 14);line-height:1.7}.notice-popup>button{display:block;width:100%;height:calc(var(--diy-unit, 1px) * 35);line-height:calc(var(--diy-unit, 1px) * 35);margin-top:calc(var(--diy-unit, 1px) * 20);border-radius:calc(var(--diy-unit, 1px) * 18);color:white;font-size:calc(var(--diy-unit, 1px) * 13);border:0;padding:0}
